-- Ported from docs/sql/2026-09-05-modular-and-catalogue.sql — now applied automatically on every boot by
-- SqlMigrationRunner (PostgreSQL only, one transaction per file, after the
-- seeders). Modular rail category + 355 listings so no sub-type chip is empty.
-- Idempotent by construction: re-running is a no-op.

-- BeSpoke shop — Modular category + a full catalogue.
--
-- 1. Adds a "Modular" rail category with 8 sub-types (Wardrobe, Kitchen, TV Unit,
--    Pantry, Shoe Rack, Storage Unit, Vanity, Dresser). Nothing existing is removed —
--    the 11 categories already on the rail stay exactly as they are.
-- 2. Adds 355 product listings — 5 in every one of the 71 sub-types, so no rail
--    entry and no sub-type chip lands on an empty grid.
--
-- Everything is filed under the vendor with slug 'bespoke-living'. Change that slug
-- below to use a different vendor. The shop only shows products from an active,
-- KYC-VERIFIED vendor — if nothing appears after running this, check kyc_status.
--
-- Photography is Unsplash (free to use, same source the rest of the seed data uses).
-- Nothing here is scraped from a retailer's site.
--
-- Safe to run twice: picklist rows are ON CONFLICT DO NOTHING, and a listing is
-- skipped if that vendor already has a product with the same name. The whole file is
-- one transaction — if any statement fails, nothing is applied.
--
--   psql "$DB_URL" -f 2026-09-05-modular-and-catalogue.sql
--
-- Check afterwards (expect 12 categories, 71 sub-types, 355+ listings):
--   SELECT shop_category, count(DISTINCT shop_sub_category) AS sub_types, count(*) AS listings
--     FROM products WHERE shop_category IS NOT NULL GROUP BY 1 ORDER BY 1;
--
-- To undo just this file:
--   DELETE FROM products p USING companies c
--    WHERE p.company_id = c.id AND c.slug = 'bespoke-living'
--      AND p.created_at >= '2026-09-05' AND p.shop_sub_category IS NOT NULL;
--   DELETE FROM platform_options
--    WHERE (list_key = 'SHOP_CATEGORY' AND value = 'Modular')
--       OR (list_key = 'SHOP_SUBCATEGORY' AND note = 'Modular');


-- ---------------------------------------------------------------- picklists ----
-- sort_order -1 puts Modular at the top of the rail without renumbering the
-- categories that are already there (the first of those sits at 0).
INSERT INTO platform_options (list_key, value, label, note, sort_order, active) VALUES
  ('SHOP_CATEGORY', 'Modular', 'Modular', NULL, -1, true)
ON CONFLICT (list_key, value) DO NOTHING;

-- Sub-types hang off their parent category through note.
INSERT INTO platform_options (list_key, value, label, note, sort_order, active) VALUES
  ('SHOP_SUBCATEGORY', 'Wardrobe', 'Wardrobe', 'Modular', 63, true),
  ('SHOP_SUBCATEGORY', 'Kitchen', 'Kitchen', 'Modular', 64, true),
  ('SHOP_SUBCATEGORY', 'TV Unit', 'TV Unit', 'Modular', 65, true),
  ('SHOP_SUBCATEGORY', 'Pantry', 'Pantry', 'Modular', 66, true),
  ('SHOP_SUBCATEGORY', 'Shoe Rack', 'Shoe Rack', 'Modular', 67, true),
  ('SHOP_SUBCATEGORY', 'Storage Unit', 'Storage Unit', 'Modular', 68, true),
  ('SHOP_SUBCATEGORY', 'Vanity', 'Vanity', 'Modular', 69, true),
  ('SHOP_SUBCATEGORY', 'Dresser', 'Dresser', 'Modular', 70, true)
ON CONFLICT (list_key, value) DO NOTHING;

-- ----------------------------------------------------------------- listings ----
INSERT INTO products
  (company_id, name, description, category, room_type, shop_category, shop_sub_category,
   price, image_url, active, created_at)
SELECT c.id, d.name, d.description, 'FURNITURE', d.room_type, d.shop_category,
       d.shop_sub_category, d.price, d.image_url, true, now()
FROM companies c
